import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Error codes","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/error-codes.md","filePath":"troubleshooting/error-codes.md","lastUpdated":null}'),i={name:"troubleshooting/error-codes.md"};function s(n,e,c,h,l,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h1><p>Every message in MeetCue shows a code such as <code>MC-AUD-001</code>. Find the code below for what it means and how to fix it. The <strong>See the fix</strong> button in the app opens this page at the right code.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><h3 id="mc-aud-001" tabindex="-1">MC-AUD-001 <a class="header-anchor" href="#mc-aud-001" aria-label="Permalink to &quot;MC-AUD-001 {#mc-aud-001}&quot;">​</a></h3><p><strong>The audio device is in exclusive use</strong> · Error</p><p>How to fix: In Sound settings, open the device&#39;s properties, and on the Advanced tab clear &quot;Allow applications to take exclusive control of this device&quot;.</p><h3 id="mc-aud-002" tabindex="-1">MC-AUD-002 <a class="header-anchor" href="#mc-aud-002" aria-label="Permalink to &quot;MC-AUD-002 {#mc-aud-002}&quot;">​</a></h3><p><strong>Microphone access is blocked</strong> · Error</p><p>How to fix: Turn on microphone access for desktop apps in the system privacy settings, then restart capture.</p><h3 id="mc-aud-003" tabindex="-1">MC-AUD-003 <a class="header-anchor" href="#mc-aud-003" aria-label="Permalink to &quot;MC-AUD-003 {#mc-aud-003}&quot;">​</a></h3><p><strong>No usable audio device was found</strong> · Error</p><p>How to fix: Connect a microphone or speakers, make sure they are enabled in Sound settings, then pick them again in Settings › Audio.</p><h3 id="mc-aud-004" tabindex="-1">MC-AUD-004 <a class="header-anchor" href="#mc-aud-004" aria-label="Permalink to &quot;MC-AUD-004 {#mc-aud-004}&quot;">​</a></h3><p><strong>The audio device changed; capture restarted</strong> · Notice</p><p>How to fix: Nothing to do. If the level bars stay flat, pick the device again in Settings › Audio.</p><h3 id="mc-aud-005" tabindex="-1">MC-AUD-005 <a class="header-anchor" href="#mc-aud-005" aria-label="Permalink to &quot;MC-AUD-005 {#mc-aud-005}&quot;">​</a></h3><p><strong>System sound capture receives only silence</strong> · Warning</p><p>How to fix: Check that the meeting plays through the default output device. Mute your speakers or use headphones while testing so the microphone does not pick up the sound instead.</p><h3 id="mc-aud-900" tabindex="-1">MC-AUD-900 <a class="header-anchor" href="#mc-aud-900" aria-label="Permalink to &quot;MC-AUD-900 {#mc-aud-900}&quot;">​</a></h3><p><strong>Audio capture is not available on this platform yet</strong> · Error</p><p>How to fix: This build supports audio capture on Windows only. Practice mode with simulated latency still works.</p><h2 id="speech-recognition" tabindex="-1">Speech recognition <a class="header-anchor" href="#speech-recognition" aria-label="Permalink to &quot;Speech recognition&quot;">​</a></h2><h3 id="mc-asr-001" tabindex="-1">MC-ASR-001 <a class="header-anchor" href="#mc-asr-001" aria-label="Permalink to &quot;MC-ASR-001 {#mc-asr-001}&quot;">​</a></h3><p><strong>The speech recognition API key was rejected</strong> · Error</p><p>How to fix: Copy the key again from the provider console, paste it in Settings › Providers, and select Verify.</p><h3 id="mc-asr-002" tabindex="-1">MC-ASR-002 <a class="header-anchor" href="#mc-asr-002" aria-label="Permalink to &quot;MC-ASR-002 {#mc-asr-002}&quot;">​</a></h3><p><strong>Could not connect to the speech recognition service</strong> · Error</p><p>How to fix: Check your network or proxy, then run the latency probe to pick a reachable endpoint.</p><h3 id="mc-asr-003" tabindex="-1">MC-ASR-003 <a class="header-anchor" href="#mc-asr-003" aria-label="Permalink to &quot;MC-ASR-003 {#mc-asr-003}&quot;">​</a></h3><p><strong>The speech recognition service is limiting requests</strong> · Warning</p><p>How to fix: Wait a minute and try again. If it keeps happening, check the quota and balance in the provider console.</p><h3 id="mc-asr-004" tabindex="-1">MC-ASR-004 <a class="header-anchor" href="#mc-asr-004" aria-label="Permalink to &quot;MC-ASR-004 {#mc-asr-004}&quot;">​</a></h3><p><strong>The speech recognition service returned an unexpected response</strong> · Error</p><p>How to fix: Update MeetCue to the latest version. If the problem persists, export diagnostics and open an issue.</p><h3 id="mc-asr-005" tabindex="-1">MC-ASR-005 <a class="header-anchor" href="#mc-asr-005" aria-label="Permalink to &quot;MC-ASR-005 {#mc-asr-005}&quot;">​</a></h3><p><strong>No speech recognition provider is set up</strong> · Error</p><p>How to fix: Choose a provider and enter its API key in Settings › Providers, or start demo mode to try MeetCue without keys.</p><h2 id="language-models" tabindex="-1">Language models <a class="header-anchor" href="#language-models" aria-label="Permalink to &quot;Language models&quot;">​</a></h2><h3 id="mc-llm-001" tabindex="-1">MC-LLM-001 <a class="header-anchor" href="#mc-llm-001" aria-label="Permalink to &quot;MC-LLM-001 {#mc-llm-001}&quot;">​</a></h3><p><strong>Hint generation timed out</strong> · Warning</p><p>How to fix: Run the latency probe and switch to a faster model or endpoint. Hints for the next question are generated as usual.</p><h3 id="mc-llm-002" tabindex="-1">MC-LLM-002 <a class="header-anchor" href="#mc-llm-002" aria-label="Permalink to &quot;MC-LLM-002 {#mc-llm-002}&quot;">​</a></h3><p><strong>The language model API key was rejected</strong> · Error</p><p>How to fix: Copy the key again from the provider console, paste it in Settings › Providers, and select Verify.</p><h3 id="mc-llm-003" tabindex="-1">MC-LLM-003 <a class="header-anchor" href="#mc-llm-003" aria-label="Permalink to &quot;MC-LLM-003 {#mc-llm-003}&quot;">​</a></h3><p><strong>The language model service is limiting requests</strong> · Warning</p><p>How to fix: MeetCue retries automatically. If it keeps happening, check the rate limits and balance of your account.</p><h3 id="mc-llm-004" tabindex="-1">MC-LLM-004 <a class="header-anchor" href="#mc-llm-004" aria-label="Permalink to &quot;MC-LLM-004 {#mc-llm-004}&quot;">​</a></h3><p><strong>The selected model is not available</strong> · Error</p><p>How to fix: Pick another model in Settings › Providers.</p><h3 id="mc-llm-005" tabindex="-1">MC-LLM-005 <a class="header-anchor" href="#mc-llm-005" aria-label="Permalink to &quot;MC-LLM-005 {#mc-llm-005}&quot;">​</a></h3><p><strong>The language model request failed</strong> · Error</p><p>How to fix: Check your network and the provider status page, then try again.</p><h3 id="mc-llm-006" tabindex="-1">MC-LLM-006 <a class="header-anchor" href="#mc-llm-006" aria-label="Permalink to &quot;MC-LLM-006 {#mc-llm-006}&quot;">​</a></h3><p><strong>The model&#39;s answer could not be read</strong> · Warning</p><p>How to fix: Usually a one-off. If it happens often, choose a more capable model for hint generation.</p><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><h3 id="mc-hk-001" tabindex="-1">MC-HK-001 <a class="header-anchor" href="#mc-hk-001" aria-label="Permalink to &quot;MC-HK-001 {#mc-hk-001}&quot;">​</a></h3><p><strong>A shortcut is already used by another program</strong> · Warning</p><p>How to fix: Open Settings › Shortcuts and assign a different key combination to the item marked in red.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><h3 id="mc-sys-001" tabindex="-1">MC-SYS-001 <a class="header-anchor" href="#mc-sys-001" aria-label="Permalink to &quot;MC-SYS-001 {#mc-sys-001}&quot;">​</a></h3><p><strong>The WebView2 runtime is missing</strong> · Error</p><p>How to fix: Install the Evergreen WebView2 Runtime from Microsoft, then start MeetCue again.</p><h3 id="mc-sys-002" tabindex="-1">MC-SYS-002 <a class="header-anchor" href="#mc-sys-002" aria-label="Permalink to &quot;MC-SYS-002 {#mc-sys-002}&quot;">​</a></h3><p><strong>The settings folder is not writable</strong> · Warning</p><p>How to fix: MeetCue saved settings to your user profile instead. Check the folder permissions if you want portable settings.</p><h3 id="mc-sys-003" tabindex="-1">MC-SYS-003 <a class="header-anchor" href="#mc-sys-003" aria-label="Permalink to &quot;MC-SYS-003 {#mc-sys-003}&quot;">​</a></h3><p><strong>The system credential store is unavailable</strong> · Error</p><p>How to fix: API keys are kept only in the system credential store. Make sure it is running (Credential Manager, Keychain or Secret Service) and try again.</p><h3 id="mc-sys-004" tabindex="-1">MC-SYS-004 <a class="header-anchor" href="#mc-sys-004" aria-label="Permalink to &quot;MC-SYS-004 {#mc-sys-004}&quot;">​</a></h3><p><strong>This feature is not supported on this platform yet</strong> · Notice</p><p>How to fix: The feature is planned for a later release. See the platform support table in the docs.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><h3 id="mc-net-001" tabindex="-1">MC-NET-001 <a class="header-anchor" href="#mc-net-001" aria-label="Permalink to &quot;MC-NET-001 {#mc-net-001}&quot;">​</a></h3><p><strong>A secure connection could not be established</strong> · Error</p><p>How to fix: If your network uses an HTTPS proxy, set the proxy address in Settings › Providers › Advanced and make sure its certificate is trusted by the system.</p><h2 id="budget" tabindex="-1">Budget <a class="header-anchor" href="#budget" aria-label="Permalink to &quot;Budget&quot;">​</a></h2><h3 id="mc-bud-001" tabindex="-1">MC-BUD-001 <a class="header-anchor" href="#mc-bud-001" aria-label="Permalink to &quot;MC-BUD-001 {#mc-bud-001}&quot;">​</a></h3><p><strong>80% of the budget is used</strong> · Warning</p><p>How to fix: Spending is close to the limit you set. Adjust the budget in Settings › Providers if needed.</p><h3 id="mc-bud-002" tabindex="-1">MC-BUD-002 <a class="header-anchor" href="#mc-bud-002" aria-label="Permalink to &quot;MC-BUD-002 {#mc-bud-002}&quot;">​</a></h3><p><strong>The budget is used up</strong> · Warning</p><p>How to fix: MeetCue applied the action you chose for this case. Raise the budget in Settings › Providers to continue.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="mc-prc-001" tabindex="-1">MC-PRC-001 <a class="header-anchor" href="#mc-prc-001" aria-label="Permalink to &quot;MC-PRC-001 {#mc-prc-001}&quot;">​</a></h3><p><strong>The practice file could not be read</strong> · Error</p><p>How to fix: Use an .srt, .vtt, .txt, .md or .csv file. See the file format reference for examples.</p><h3 id="mc-prc-002" tabindex="-1">MC-PRC-002 <a class="header-anchor" href="#mc-prc-002" aria-label="Permalink to &quot;MC-PRC-002 {#mc-prc-002}&quot;">​</a></h3><p><strong>Speech synthesis is not available</strong> · Warning</p><p>How to fix: Install a text-to-speech voice for the question language in the system settings, or practice with on-screen questions only.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><h3 id="mc-diag-001" tabindex="-1">MC-DIAG-001 <a class="header-anchor" href="#mc-diag-001" aria-label="Permalink to &quot;MC-DIAG-001 {#mc-diag-001}&quot;">​</a></h3><p><strong>Diagnostics could not be exported</strong> · Error</p><p>How to fix: Pick a folder you can write to, for example Documents, and try again.</p><hr><p>Still stuck? <a href="./diagnostics">Export diagnostics</a> and open an issue with the code.</p>',97)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
